import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function DriverDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [availableDeliveries, setAvailableDeliveries] = useState([]);
  const [activeJobs, setActiveJobs] = useState([]);
  const [history, setHistory] = useState([]);
  const [earnings, setEarnings] = useState({ total: 0, weekly: 0, today: 0, perDelivery: 20, totalDeliveries: 0, pendingPayout: 0 });
  const [pendingDeliveries, setPendingDeliveries] = useState([]);
  const [completedPayouts, setCompletedPayouts] = useState([]);
  const [monthlySummary, setMonthlySummary] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [currentLocation, setCurrentLocation] = useState({ lat: -1.286389, lng: 36.817223, address: 'Nairobi, Kenya' });
  const [showLocationModal, setShowLocationModal] = useState(false);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [showBankModal, setShowBankModal] = useState(false);
  const [showEditProfileModal, setShowEditProfileModal] = useState(false);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [filterStatus, setFilterStatus] = useState('all');

  // Profile Data
  const [profileData, setProfileData] = useState({
    firstName: user?.firstName || '',
    lastName: user?.lastName || '',
    email: user?.email || '',
    phone: user?.phone || '',
    driversLicense: user?.driversLicense || '',
    address: user?.address || ''
  });
  const [editProfileData, setEditProfileData] = useState(profileData);

  // Settings Data
  const [settings, setSettings] = useState({
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    darkMode: false,
    language: 'english'
  });

  // Bank Account State
  const [bankAccount, setBankAccount] = useState({
    accountName: '',
    accountNumber: '',
    bankName: '',
    routingNumber: ''
  });
  const [hasBankAccount, setHasBankAccount] = useState(false);
  const [loadingBank, setLoadingBank] = useState(false);

  const [vehicleInfo, setVehicleInfo] = useState({
    model: user?.vehicleModel || 'Toyota Camry',
    color: user?.vehicleColor || 'White',
    plate: user?.vehiclePlate || 'KCA 123A',
    year: user?.vehicleYear || 2022
  });

  const [driverStats, setDriverStats] = useState({
    rating: 4.8, totalRatings: 0, acceptanceRate: 98, onTimeRate: 96, totalDistance: 0, totalHours: 0
  });

  const [notifications] = useState([
    { id: 1, type: 'new_delivery', title: 'New Delivery Available!', message: 'Pickup from John Doe', time: '2 hours ago', read: false, icon: '📦' }
  ]);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
    fetchBankAccount();
    fetchPayoutHistory();
    const interval = setInterval(fetchAllData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const dashboardRes = await fetch('http://localhost:5000/api/driver/dashboard', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const dashboardData = await dashboardRes.json();
      if (dashboardData.success) {
        const data = dashboardData.data;
        setAvailableDeliveries(data.deliveries?.available || []);
        setActiveJobs(data.deliveries?.active || []);
        setHistory(data.deliveries?.history || []);
        setEarnings(data.earnings || { total: 0, weekly: 0, today: 0, perDelivery: 20, totalDeliveries: 0, pendingPayout: 0 });
        setDriverStats(data.stats || { rating: 4.8, acceptanceRate: 98, onTimeRate: 96 });
        setIsOnline(data.isOnline || false);
        if (data.currentLocation) setCurrentLocation(data.currentLocation);
        setProfileData({
          firstName: data.profile?.firstName || user?.firstName,
          lastName: data.profile?.lastName || user?.lastName,
          email: data.profile?.email || user?.email,
          phone: data.profile?.phone || user?.phone,
          driversLicense: data.profile?.driversLicense || '',
          address: data.profile?.address || ''
        });
      }
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchBankAccount = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/bank-account', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success && data.bankAccount) {
        setBankAccount(data.bankAccount);
        setHasBankAccount(true);
      }
    } catch (error) {
      console.error('Error fetching bank account:', error);
    }
  };

  const fetchPayoutHistory = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/payout-history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setPendingDeliveries(data.pendingDeliveries || []);
        setCompletedPayouts(data.completedPayouts || []);
        setMonthlySummary(data.monthlySummary || []);
        setEarnings(prev => ({ ...prev, pendingPayout: data.pendingTotal || 0 }));
      }
    } catch (error) {
      console.error('Error fetching payout history:', error);
    }
  };

  const saveBankAccount = async (e) => {
    e.preventDefault();
    setLoadingBank(true);
    try {
      const res = await fetch('http://localhost:5000/api/driver/bank-account', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(bankAccount)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Bank account saved successfully!');
        setHasBankAccount(true);
        setShowBankModal(false);
      } else {
        toast.error(data.error || 'Failed to save bank account');
      }
    } catch (error) {
      toast.error('Failed to save bank account');
    } finally {
      setLoadingBank(false);
    }
  };

  const deleteBankAccount = async () => {
    if (window.confirm('Are you sure you want to remove your bank account details?')) {
      try {
        const res = await fetch('http://localhost:5000/api/driver/bank-account', {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Bank account removed');
          setHasBankAccount(false);
          setBankAccount({ accountName: '', accountNumber: '', bankName: '', routingNumber: '' });
        }
      } catch (error) {
        toast.error('Failed to remove bank account');
      }
    }
  };

  const requestPayout = async () => {
    if (!payoutAmount || parseFloat(payoutAmount) <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (parseFloat(payoutAmount) > earnings.pendingPayout) {
      toast.error('Amount exceeds available balance');
      return;
    }
    if (!hasBankAccount) {
      toast.error('Please add a bank account first');
      setShowBankModal(true);
      return;
    }
    
    try {
      const res = await fetch('http://localhost:5000/api/driver/payout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ amount: parseFloat(payoutAmount) })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(data.message);
        setShowPayoutModal(false);
        setPayoutAmount('');
        fetchPayoutHistory();
        fetchAllData();
      } else {
        toast.error(data.error);
      }
    } catch (error) {
      toast.error('Failed to request payout');
    }
  };

  const updateDriverStatus = async (online) => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/status', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ isOnline: online })
      });
      const data = await res.json();
      if (data.success) {
        setIsOnline(online);
        toast.success(online ? 'You are now online!' : 'You are now offline');
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const acceptDelivery = async (deliveryId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/accept/${deliveryId}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Delivery accepted!');
        fetchAllData();
      } else {
        toast.error(data.error || 'Failed to accept');
      }
    } catch (error) {
      toast.error('Error accepting delivery');
    }
  };

  const updateDeliveryStatus = async (deliveryId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/delivery/${deliveryId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Delivery marked as ${status}!`);
        fetchAllData();
      } else {
        toast.error('Failed to update status');
      }
    } catch (error) {
      toast.error('Error updating status');
    }
  };

  const updateVehicleInfo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/driver/vehicle', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(vehicleInfo)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Vehicle info updated!');
        setShowVehicleModal(false);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update vehicle');
    }
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/driver/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(editProfileData)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Profile updated successfully!');
        setProfileData(editProfileData);
        setShowEditProfileModal(false);
      } else {
        toast.error(data.error || 'Failed to update profile');
      }
    } catch (error) {
      toast.error('Failed to update profile');
    }
  };

  const updateSettings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/settings', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(settings)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Settings saved!');
      } else {
        toast.error(data.error || 'Failed to save settings');
      }
    } catch (error) {
      toast.error('Failed to save settings');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b', confirmed: '#10b981', 'in-progress': '#3b82f6',
      completed: '#8b5cf6', cancelled: '#ef4444', 'driver-assigned': '#8b5cf6',
      pickup: '#3b82f6', 'en-route': '#10b981'
    };
    const labels = {
      pending: '⏳ Pending', confirmed: '✓ Confirmed', 'in-progress': '🔧 In Progress',
      completed: '✅ Completed', cancelled: '❌ Cancelled', 'driver-assigned': '🚗 Assigned',
      pickup: '📍 Pickup', 'en-route': '🚚 En Route'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const getDistanceText = () => {
    const distances = ['0.5 miles away', '1.2 miles away', '0.8 miles away', '1.5 miles away'];
    return distances[Math.floor(Math.random() * distances.length)];
  };

  const getEtaText = () => {
    const etas = ['5-10 min', '10-15 min', '8-12 min', '12-18 min'];
    return etas[Math.floor(Math.random() * etas.length)];
  };

  const filteredHistory = filterStatus === 'all' ? history : history.filter(h => h.status === filterStatus);
  const todayEarnings = earnings.today || 0;
  const todayCompleted = history.filter(d => {
    const today = new Date();
    const deliveryDate = new Date(d.completedAt || d.createdAt);
    return d.status === 'completed' && 
      deliveryDate.getDate() === today.getDate() &&
      deliveryDate.getMonth() === today.getMonth() &&
      deliveryDate.getFullYear() === today.getFullYear();
  }).length;

  const todayHours = todayCompleted * 0.75;
  const todayDistance = todayCompleted * 8;

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />
      
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <div>
            <h1 style={styles.logoText}>Car Care Connect - Driver</h1>
            <div style={styles.headerSubtitle}>{profileData.firstName} {profileData.lastName} · ⭐ {driverStats.rating} · 📍 {currentLocation.address.split(',')[0]}</div>
          </div>
        </div>
        <div style={styles.headerRight}>
          <button style={{ ...styles.onlineToggle, backgroundColor: isOnline ? '#10b981' : '#ef4444' }} onClick={() => updateDriverStatus(!isOnline)}>
            <span style={styles.onlineDot}></span>{isOnline ? 'Online' : 'Offline'}
          </button>
          <button style={styles.locationBtn} onClick={() => setShowLocationModal(true)}>📍</button>
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>🔔{unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}</div>
          <div style={styles.userInfo}>
            <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${profileData.firstName}`} alt="avatar" style={styles.avatar} />
            <button onClick={onLogout} style={styles.logoutButton}>🚪</button>
          </div>
        </div>
      </div>

      {/* Stats Cards - REAL EARNINGS DATA */}
      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>💰 Today</h3><p style={styles.statNumber}>${todayEarnings}</p></div>
        <div style={styles.statCard}><h3>📊 Weekly</h3><p style={styles.statNumber}>${earnings.weekly}</p></div>
        <div style={styles.statCard}><h3>🏆 Total</h3><p style={styles.statNumber}>${earnings.total}</p></div>
        <div style={styles.statCard}><h3>📦 Deliveries</h3><p style={styles.statNumber}>{earnings.totalDeliveries}</p></div>
        <div style={styles.statCard}><h3>⭐ Rating</h3><p style={styles.statNumber}>{driverStats.rating}</p></div>
        <div style={styles.statCard}><h3>💰 Pending</h3><p style={styles.statNumber}>${earnings.pendingPayout}<button style={styles.payoutBtn} onClick={() => setShowPayoutModal(true)}>Request</button></p></div>
      </div>

      {/* Quick Stats */}
      <div style={styles.quickStats}>
        <div style={styles.quickStat}><span>🚗</span> Online: {isOnline ? 'Yes' : 'No'}</div>
        <div style={styles.quickStat}><span>📦</span> Available: {availableDeliveries.length}</div>
        <div style={styles.quickStat}><span>🚚</span> Active: {activeJobs.length}</div>
        <div style={styles.quickStat}><span>⏱️</span> Hours: {driverStats.totalHours}h</div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'available' ? styles.activeTab : {})}} onClick={() => setActiveTab('available')}>📦 Available ({availableDeliveries.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'active' ? styles.activeTab : {})}} onClick={() => setActiveTab('active')}>🚗 Active ({activeJobs.length})</button>
        <button style={{...styles.tab, ...(activeTab === 'history' ? styles.activeTab : {})}} onClick={() => setActiveTab('history')}>📋 History</button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
        <button style={{...styles.tab, ...(activeTab === 'vehicle' ? styles.activeTab : {})}} onClick={() => setActiveTab('vehicle')}>🚗 Vehicle</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
        <button style={{...styles.tab, ...(activeTab === 'settings' ? styles.activeTab : {})}} onClick={() => setActiveTab('settings')}>⚙️ Settings</button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {/* Dashboard Tab */}
            {activeTab === 'dashboard' && (
              <div style={styles.twoColumn}>
                <div>
                  <div style={styles.card}>
                    <h3>📊 Today's Performance</h3>
                    <div style={styles.performanceItem}><span>Deliveries Completed:</span><span style={styles.performanceValue}>{todayCompleted}</span></div>
                    <div style={styles.performanceItem}><span>Hours Worked:</span><span style={styles.performanceValue}>{todayHours.toFixed(1)}h</span></div>
                    <div style={styles.performanceItem}><span>Distance Covered:</span><span style={styles.performanceValue}>{todayDistance} miles</span></div>
                    <div style={styles.performanceItem}><span>Rating Received:</span><span style={styles.performanceValue}>⭐ {driverStats.rating}</span></div>
                  </div>
                  <div style={styles.card}>
                    <h3>📈 Performance Stats</h3>
                    <div style={styles.metricItem}><span>Acceptance Rate:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${driverStats.acceptanceRate}%`, backgroundColor: '#10b981' }}></div></div><span>{driverStats.acceptanceRate}%</span></div>
                    <div style={styles.metricItem}><span>On-Time Rate:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${driverStats.onTimeRate}%`, backgroundColor: '#3b82f6' }}></div></div><span>{driverStats.onTimeRate}%</span></div>
                    <div style={styles.metricItem}><span>Customer Rating:</span><div style={styles.progressBar}><div style={{ ...styles.progressFill, width: `${(driverStats.rating / 5) * 100}%`, backgroundColor: '#f59e0b' }}></div></div><span>⭐ {driverStats.rating}</span></div>
                  </div>
                </div>
                <div>
                  <div style={styles.card}>
                    <h3>📍 Current Location</h3>
                    <div style={styles.locationInfo}><span>📌 {currentLocation.address}</span><button style={styles.updateLocationBtn} onClick={() => setShowLocationModal(true)}>Update</button></div>
                    <div style={styles.mapPlaceholder}>🗺️ Map View - Live tracking active</div>
                  </div>
                  <div style={styles.card}>
                    <h3>🚗 Active Jobs ({activeJobs.length})</h3>
                    {activeJobs.length === 0 ? <p>No active jobs</p> : activeJobs.map(job => (
                      <div key={job._id} style={styles.activeJobItem}><div><strong>{job.serviceName}</strong></div><div>Customer: {job.customerId?.firstName}</div><span style={getStatusBadge(job.status)}>{job.status}</span></div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Available Deliveries Tab */}
            {activeTab === 'available' && (
              <div>
                <div style={styles.sectionHeader}><h2>📦 Available Deliveries ({availableDeliveries.length})</h2><span style={styles.onlineBadge}>🟢 You are {isOnline ? 'Online' : 'Offline'}</span></div>
                {availableDeliveries.length === 0 ? (
                  <div style={styles.emptyState}>No available deliveries</div>
                ) : (
                  availableDeliveries.map(delivery => (
                    <div key={delivery._id} style={styles.deliveryCard}>
                      <div style={styles.deliveryHeader}><span style={styles.deliveryType}>🚗 Concierge Pickup</span><span style={getStatusBadge(delivery.status)}>{delivery.status}</span></div>
                      <div style={styles.deliveryContent}>
                        <div style={styles.pickupInfo}><span style={styles.infoIcon}>📍</span><div><strong>Pickup Location:</strong><p>{delivery.pickupAddress || delivery.customerId?.address || 'Customer address'}</p><span style={styles.distanceBadge}>{getDistanceText()}</span></div></div>
                        <div style={styles.arrowIcon}>↓</div>
                        <div style={styles.shopInfo}><span style={styles.infoIcon}>🔧</span><div><strong>Service Center:</strong><p>{delivery.providerId?.businessName || 'Auto Service Center'}</p><p>Service: {delivery.serviceName}</p></div></div>
                      </div>
                      <div style={styles.deliveryFooter}><div><span style={styles.etaBadge}>⏱️ ETA: {getEtaText()}</span><span style={styles.priceBadge}>💰 ${earnings.perDelivery}</span></div><button style={styles.acceptBtn} onClick={() => acceptDelivery(delivery._id)}>Accept Delivery →</button></div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Active Jobs Tab */}
            {activeTab === 'active' && (
              <div>
                <h2>🚗 Active Jobs ({activeJobs.length})</h2>
                {activeJobs.length === 0 ? <div style={styles.emptyState}>No active jobs</div> : activeJobs.map(job => (
                  <div key={job._id} style={styles.activeCard}>
                    <div style={styles.activeHeader}><span style={styles.activeType}>🚗 Active Delivery</span><span style={getStatusBadge(job.status)}>{job.status}</span></div>
                    <div style={styles.progressSteps}>
                      <div style={{...styles.step, ...(job.status === 'confirmed' ? styles.stepActive : styles.stepCompleted)}}><span>1</span> Pickup</div><div style={styles.stepLine}></div>
                      <div style={{...styles.step, ...(job.status === 'in-progress' ? styles.stepActive : {})}}><span>2</span> Drop-off</div><div style={styles.stepLine}></div>
                      <div style={{...styles.step, ...(job.status === 'completed' ? styles.stepActive : {})}}><span>3</span> Complete</div>
                    </div>
                    <div style={styles.jobDetails}>
                      <p><strong>Customer:</strong> {job.customerId?.firstName} {job.customerId?.lastName}</p>
                      <p><strong>Phone:</strong> {job.customerId?.phone || 'N/A'}</p>
                      <p><strong>Service:</strong> {job.serviceName}</p>
                      <p><strong>Shop:</strong> {job.providerId?.businessName}</p>
                    </div>
                    <div style={styles.actionButtons}>
                      {job.status === 'confirmed' && <button style={styles.pickupBtn} onClick={() => updateDeliveryStatus(job._id, 'in-progress')}>📍 Confirm Pickup</button>}
                      {job.status === 'in-progress' && <button style={styles.completeBtn} onClick={() => updateDeliveryStatus(job._id, 'completed')}>✅ Complete Delivery</button>}
                      <button style={styles.contactBtn}>📞 Contact Customer</button>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* History Tab */}
            {activeTab === 'history' && (
              <div>
                <div style={styles.historyHeader}><h2>📋 Delivery History</h2><select style={styles.filterSelect} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}><option value="all">All</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>
                {filteredHistory.length === 0 ? <div style={styles.emptyState}>No deliveries yet</div> : filteredHistory.map(delivery => (
                  <div key={delivery._id} style={styles.historyCard}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div><p><strong>{delivery.serviceName}</strong></p><p>Customer: {delivery.customerId?.firstName} {delivery.customerId?.lastName}</p><p>📅 {new Date(delivery.bookingDate).toLocaleDateString()}</p></div>
                      <div style={{ textAlign: 'right' }}><span style={getStatusBadge(delivery.status)}>{delivery.status}</span><p style={styles.earningText}>+${earnings.perDelivery}</p></div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Earnings Tab - WITH PER-DELIVERY BREAKDOWN */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsHeader}>
                  <h2>💰 Earnings & Payouts</h2>
                  <button style={styles.payoutRequestBtn} onClick={() => setShowPayoutModal(true)}>Request Payout</button>
                </div>
                
                <div style={styles.earningsGrid}>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>💰</span><h3>Total Earnings</h3><p style={styles.earningsAmount}>${earnings.total}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>📊</span><h3>This Week</h3><p style={styles.earningsAmount}>${earnings.weekly}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>📦</span><h3>Today</h3><p style={styles.earningsAmount}>${earnings.today}</p></div>
                  <div style={styles.earningsCard}><span style={styles.earningsIcon}>🚗</span><h3>Total Deliveries</h3><p style={styles.earningsAmount}>{earnings.totalDeliveries}</p></div>
                </div>

                {/* Pending Deliveries - Per Delivery Breakdown */}
                <div style={styles.card}>
                  <h3>📋 Pending Deliveries ({pendingDeliveries.length})</h3>
                  <p style={styles.pendingTotal}>Total Pending: <strong>${earnings.pendingPayout}</strong></p>
                  {pendingDeliveries.length === 0 ? (
                    <div style={styles.emptyState}>No pending deliveries</div>
                  ) : (
                    <div style={styles.pendingList}>
                      {pendingDeliveries.map(delivery => (
                        <div key={delivery.id} style={styles.pendingItem}>
                          <div>
                            <strong>{delivery.serviceName}</strong>
                            <div style={styles.pendingDate}>{new Date(delivery.date).toLocaleDateString()}</div>
                          </div>
                          <div style={styles.pendingAmount}>+${delivery.amount}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {/* Completed Payouts */}
                <div style={styles.card}>
                  <h3>✅ Completed Payouts</h3>
                  {completedPayouts.length === 0 ? (
                    <div style={styles.emptyState}>No completed payouts yet</div>
                  ) : (
                    <div style={styles.payoutList}>
                      {completedPayouts.map(payout => (
                        <div key={payout.id} style={styles.payoutItem}>
                          <div>
                            <strong>{payout.serviceName}</strong>
                            <div style={styles.payoutDate}>{new Date(payout.date).toLocaleDateString()}</div>
                          </div>
                          <div style={styles.payoutAmount}>+${payout.amount}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {/* Monthly Summary */}
                <div style={styles.card}>
                  <h3>📊 Monthly Summary</h3>
                  {monthlySummary.length === 0 ? (
                    <div style={styles.emptyState}>No payout history yet</div>
                  ) : (
                    <div style={styles.monthlyList}>
                      {monthlySummary.map(month => (
                        <div key={month._id} style={styles.monthlyItem}>
                          <span>{month._id}</span>
                          <span>{month.count} deliveries</span>
                          <span style={styles.monthlyAmount}>${month.amount}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div style={styles.infoCard}>
                  <h3>💡 How It Works</h3>
                  <ul style={styles.infoList}>
                    <li>💰 <strong>${earnings.perDelivery}</strong> per delivery + customer tips</li>
                    <li>🕐 Average delivery time: 30-45 minutes</li>
                    <li>📊 Payments accumulate and can be requested for payout</li>
                    <li>⭐ Maintain 4.5+ rating for bonus opportunities</li>
                    <li>💸 Payouts processed within 3-5 business days</li>
                    <li>🏦 Bank account required for payouts</li>
                  </ul>
                </div>
              </div>
            )}

            {/* Vehicle Tab */}
            {activeTab === 'vehicle' && (
              <div style={styles.vehicleContainer}>
                <div style={styles.vehicleHeader}><h2>🚗 My Vehicle</h2><button style={styles.editBtn} onClick={() => setShowVehicleModal(true)}>✏️ Edit</button></div>
                <div style={styles.vehicleCard}><div style={styles.vehicleIcon}>🚗</div><div style={styles.vehicleDetails}><h3>{vehicleInfo.year} {vehicleInfo.model}</h3><p>Color: {vehicleInfo.color}</p><p>License Plate: {vehicleInfo.plate}</p></div></div>
              </div>
            )}

            {/* Profile Tab - EDITABLE */}
            {activeTab === 'profile' && (
              <div style={styles.profileContainer}>
                <div style={styles.profileHeader}>
                  <img src={`https://ui-avatars.com/api/?background=2563eb&color=fff&name=${profileData.firstName} ${profileData.lastName}&size=100`} alt="avatar" style={styles.profileAvatar} />
                  <div>
                    <h2>{profileData.firstName} {profileData.lastName}</h2>
                    <p>⭐ {driverStats.rating} • Member since {new Date(user?.createdAt || Date.now()).toLocaleDateString()}</p>
                    <button style={styles.editProfileBtn} onClick={() => setShowEditProfileModal(true)}>✏️ Edit Profile</button>
                  </div>
                </div>
                <div style={styles.profileInfo}>
                  <div><strong>📧 Email:</strong> {profileData.email}</div>
                  <div><strong>📞 Phone:</strong> {profileData.phone}</div>
                  <div><strong>🚗 Driver's License:</strong> {profileData.driversLicense || 'N/A'}</div>
                  <div><strong>📍 Address:</strong> {profileData.address || 'Not set'}</div>
                  <div><strong>📦 Total Deliveries:</strong> {earnings.totalDeliveries}</div>
                  <div><strong>✅ Acceptance Rate:</strong> {driverStats.acceptanceRate}%</div>
                </div>

                {/* Bank Account Section */}
                <div style={styles.bankSection}>
                  <h3>🏦 Payout Information</h3>
                  {hasBankAccount ? (
                    <div style={styles.bankCard}>
                      <div><strong>Account Holder:</strong> {bankAccount.accountName}</div>
                      <div><strong>Account Number:</strong> ••••{bankAccount.accountNumber?.slice(-4)}</div>
                      <div><strong>Bank Name:</strong> {bankAccount.bankName}</div>
                      <div style={styles.bankActions}>
                        <button style={styles.editBankBtn} onClick={() => setShowBankModal(true)}>✏️ Update</button>
                        <button style={styles.deleteBankBtn} onClick={deleteBankAccount}>🗑️ Remove</button>
                      </div>
                    </div>
                  ) : (
                    <div style={styles.noBankCard}>
                      <p>No bank account added yet.</p>
                      <button style={styles.addBankBtn} onClick={() => setShowBankModal(true)}>+ Add Bank Account</button>
                    </div>
                  )}
                  <p style={styles.bankNote}>Your earnings will be deposited to this account. Please ensure details are correct.</p>
                </div>
              </div>
            )}

            {/* Settings Tab */}
            {activeTab === 'settings' && (
              <div style={styles.settingsContainer}>
                <h2>⚙️ Settings</h2>
                
                <div style={styles.settingsSection}>
                  <h3>🔔 Notification Preferences</h3>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.emailNotifications} onChange={(e) => setSettings({...settings, emailNotifications: e.target.checked})} /> Email Notifications</label>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.pushNotifications} onChange={(e) => setSettings({...settings, pushNotifications: e.target.checked})} /> Push Notifications</label>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.smsNotifications} onChange={(e) => setSettings({...settings, smsNotifications: e.target.checked})} /> SMS Notifications</label>
                </div>

                <div style={styles.settingsSection}>
                  <h3>🌐 Language & Region</h3>
                  <select style={styles.settingsSelect} value={settings.language} onChange={(e) => setSettings({...settings, language: e.target.value})}>
                    <option value="english">English</option>
                    <option value="spanish">Spanish</option>
                    <option value="french">French</option>
                  </select>
                </div>

                <div style={styles.settingsSection}>
                  <h3>🎨 Appearance</h3>
                  <label style={styles.settingItem}><input type="checkbox" checked={settings.darkMode} onChange={(e) => setSettings({...settings, darkMode: e.target.checked})} /> Dark Mode</label>
                </div>

                <button style={styles.saveSettingsBtn} onClick={updateSettings}>Save Settings</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Edit Profile Modal */}
      {showEditProfileModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>✏️ Edit Profile</h2>
            <form onSubmit={updateProfile}>
              <input style={styles.input} type="text" placeholder="First Name" value={editProfileData.firstName} onChange={(e) => setEditProfileData({...editProfileData, firstName: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Last Name" value={editProfileData.lastName} onChange={(e) => setEditProfileData({...editProfileData, lastName: e.target.value})} required />
              <input style={styles.input} type="email" placeholder="Email" value={editProfileData.email} onChange={(e) => setEditProfileData({...editProfileData, email: e.target.value})} required />
              <input style={styles.input} type="tel" placeholder="Phone" value={editProfileData.phone} onChange={(e) => setEditProfileData({...editProfileData, phone: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Driver's License" value={editProfileData.driversLicense} onChange={(e) => setEditProfileData({...editProfileData, driversLicense: e.target.value})} />
              <input style={styles.input} type="text" placeholder="Address" value={editProfileData.address} onChange={(e) => setEditProfileData({...editProfileData, address: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save Changes</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowEditProfileModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Bank Account Modal */}
      {showBankModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>🏦 Bank Account Details</h2>
            <form onSubmit={saveBankAccount}>
              <input style={styles.input} type="text" placeholder="Account Holder Name" value={bankAccount.accountName} onChange={(e) => setBankAccount({...bankAccount, accountName: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Account Number" value={bankAccount.accountNumber} onChange={(e) => setBankAccount({...bankAccount, accountNumber: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Bank Name" value={bankAccount.bankName} onChange={(e) => setBankAccount({...bankAccount, bankName: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Routing Number / IFSC Code" value={bankAccount.routingNumber} onChange={(e) => setBankAccount({...bankAccount, routingNumber: e.target.value})} required />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn} disabled={loadingBank}>{loadingBank ? 'Saving...' : 'Save Bank Account'}</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowBankModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Payout Modal */}
      {showPayoutModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>💰 Request Payout</h2>
            <p>Available for payout: <strong>${earnings.pendingPayout}</strong></p>
            <p>Per delivery: <strong>${earnings.perDelivery}</strong></p>
            <input style={styles.input} type="number" placeholder="Amount" value={payoutAmount} onChange={(e) => setPayoutAmount(e.target.value)} />
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={requestPayout}>Request Payout</button>
              <button style={styles.cancelBtn} onClick={() => { setShowPayoutModal(false); setPayoutAmount(''); }}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Location Modal */}
      {showLocationModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>📍 Update Location</h2>
            <input style={styles.input} type="text" placeholder="Address" value={currentLocation.address} onChange={(e) => setCurrentLocation({...currentLocation, address: e.target.value})} />
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={() => { updateDriverLocation(currentLocation.lat, currentLocation.lng); setShowLocationModal(false); toast.success('Location updated!'); }}>Save Location</button>
              <button style={styles.cancelBtn} onClick={() => setShowLocationModal(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>🚗 Update Vehicle Info</h2>
            <form onSubmit={updateVehicleInfo}>
              <input style={styles.input} type="text" placeholder="Vehicle Model" value={vehicleInfo.model} onChange={(e) => setVehicleInfo({...vehicleInfo, model: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Color" value={vehicleInfo.color} onChange={(e) => setVehicleInfo({...vehicleInfo, color: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="License Plate" value={vehicleInfo.plate} onChange={(e) => setVehicleInfo({...vehicleInfo, plate: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Year" value={vehicleInfo.year} onChange={(e) => setVehicleInfo({...vehicleInfo, year: e.target.value})} required />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

