  performanceItem: { display: 'flex', justifyContent: 'space-between', padding: '10px 0', borderBottom: '1px solid #e5e7eb' }, performanceValue: { fontWeight: 'bold', color: '#2563eb' },
  locationInfo: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }, updateLocationBtn: { backgroundColor: '#3b82f6', color: 'white', border: 'none', padding: '5px 12px', borderRadius: '5px', cursor: 'pointer' },
  mapPlaceholder: { backgroundColor: '#e5e7eb', height: '120px', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#6b7280' },
