  deliveryHeader: { backgroundColor: '#f9fafb', padding: '15px 20px', borderBottom: '1px solid #e5e7eb', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  deliveryType: { fontWeight: 'bold', color: '#f59e0b' }, deliveryContent: { padding: '20px', display: 'flex', alignItems: 'center', gap: '20px', flexWrap: 'wrap' },
  pickupInfo: { flex: 1, display: 'flex', gap: '15px', alignItems: 'flex-start' }, shopInfo: { flex: 1, display: 'flex', gap: '15px', alignItems: 'flex-start' },
  infoIcon: { fontSize: '24px' }, arrowIcon: { fontSize: '20px', color: '#9ca3af' }, distanceBadge: { display: 'inline-block', backgroundColor: '#e0e7ff', color: '#4338ca', padding: '2px 8px', borderRadius: '12px', fontSize: '12px', marginTop: '5px' },
  etaBadge: { display: 'inline-block', backgroundColor: '#f3e8ff', color: '#7c3aed', padding: '4px 12px', borderRadius: '15px', fontSize: '12px', marginRight: '10px' },
  priceBadge: { display: 'inline-block', backgroundColor: '#d1fae5', color: '#065f46', padding: '4px 12px', borderRadius: '15px', fontSize: '12px' },
  deliveryFooter: { padding: '15px 20px', borderTop: '1px solid #e5e7eb', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' },
  acceptBtn: { backgroundColor: '#10b981', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' },
  activeCard: { backgroundColor: 'white', borderRadius: '12px', marginBottom: '20px', overflow: 'hidden', boxShadow: '0 1px 3px rgba(0,0,0,0.1)' },
